SELECT e.id, e.salary AS employee_salary, e.job_title AS employee_job_title, e.full_name AS employee_full_name, m.dept_id AS manager_dept_id, m.level AS manager_level, m.full_name AS manager_full_name, CASE WHEN e.level IN ('L2', 'L5') THEN 'Priority' ELSE 'Other' END AS level_group FROM employees e LEFT OUTER JOIN employees m ON e.manager_id = m.id WHERE LOWER(e.full_name) LIKE '%aro%' AND UPPER(TRIM(e.email)) = 'CAROL@COMPANY.CO';
